function notFound(message='We could not find that page.'){app.innerHTML=`${header()}<main id="main-content" class="not-found"><span>404</span><h1>Something seems<br><em>out of place.</em></h1><p>${e(message)}</p><a class="btn-primary" href="/" data-link>Return home ${icon('arrow')}</a></main>${footer()}`;}
async function render(){
  const route=location.pathname;st.route=route;document.body.classList.toggle('portal-page',route.startsWith('/portal'));
  if(['/', '/properties', '/map', '/communities', '/about', '/contact'].includes(route)||/^\/(buy|rent)\/(dubai-marina|jbr|business-bay)\/[a-z0-9-]+\/?$/.test(route)){
    request('/api/analytics/view',{method:'POST',body:JSON.stringify({path:route.replace(/\/$/,'')||'/'})}).catch(()=>{});
  }
  app.innerHTML='<div class="startup"><div class="monogram">MG</div><p>THE MARINA GATE EXPERIENCE</p></div>';
  try{
    if(route.startsWith('/portal')){
      if(!st.user)return setRoute('/login');
      if(route==='/portal'||route==='/portal/')return await dashboard();
      if(route==='/portal/listings')return await portalListings();
      if(route==='/portal/leads')return await portalLeads();
      if(route==='/portal/team')return await portalTeam();
      if(route==='/portal/activity')return await portalAudit();
      if(route==='/portal/settings')return portalSettings();
      if(route==='/portal/import')return await portalImport();
      if(route==='/portal/listings/new'||/^\/portal\/listings\/\d+\/edit$/.test(route))return await portalEditor();
      return notFound();
    }
    if(route==='/')return await home();
    if(route==='/properties')return await catalog();
    if(route==='/map')return mapPage();
    if(route==='/login')return login();
    if(route==='/communities')return communities();
    if(route==='/about')return about();
    if(route==='/contact')return contact();
    if(/^\/(buy|rent)\/(dubai-marina|jbr|business-bay)\/[a-z0-9-]+\/?$/.test(route))return await detail();
    return notFound();
  }catch(err){console.error(err);notFound(err.message);notify(err.message,'error');}
}
async function uploadFile(file){
  if(!file.type.startsWith('image/'))throw Error('Choose an image file.');
  if(file.size>40*1024*1024)throw Error('Original image must be under 40 MB.');
  let img;
  if(typeof createImageBitmap==='function')img=await createImageBitmap(file);
  else {const url=URL.createObjectURL(file);try{img=await new Promise((resolve,reject)=>{const el=new Image();el.onload=()=>resolve(el);el.onerror=()=>reject(Error('Cannot read this image.'));el.src=url;});}finally{URL.revokeObjectURL(url);}}
  const width=Math.min(1600,img.width),height=Math.round(img.height*width/img.width);
  const canvas=document.createElement('canvas');canvas.width=width;canvas.height=height;
  canvas.getContext('2d',{alpha:false}).drawImage(img,0,0,width,height);img.close?.();
  let blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/webp',0.76));
  if(!blob||blob.type!=='image/webp')blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',0.74));
  if(!blob)throw Error('The browser could not optimize this image.');
  if(blob.size>2*1024*1024)throw Error('Optimized file remains too large; choose a smaller image.');
  const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(blob);});
  const response=await request('/api/uploads',{method:'POST',body:JSON.stringify({data})});return response.url;
}
function fileDownload(name,text,type='text/csv;charset=utf-8'){const b=new Blob([text],{type}),u=URL.createObjectURL(b),link=document.createElement('a');link.href=u;link.download=name;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(u),1000);}

document.addEventListener('click',async ev=>{
  const link=ev.target.closest('a[data-link]');if(link&&!(ev.ctrlKey||ev.metaKey||ev.shiftKey||ev.altKey)&&!link.target){ev.preventDefault();setRoute(link.getAttribute('href'));return;}
  const btn=ev.target.closest('[data-action]');if(!btn)return;
  const action=btn.dataset.action;
  try{
    if(action==='toggle-menu'){const nav=document.getElementById('mobile-nav');const open=nav?.classList.toggle('open');btn.setAttribute('aria-expanded',String(!!open));return;}
    if(action==='toggle-sidebar'){document.querySelector('.portal-sidebar')?.classList.toggle('open');return;}
    if(action==='close-modal'){document.querySelector('.modal-overlay')?.remove();return;}
    if(action==='pick-photo'||action==='photo-next'||action==='photo-prev'){
      const photos=st.property?.photos?.length?st.property.photos:['/assets/fallback.svg'];
      st.selectedPhoto=action==='pick-photo'?Number(btn.dataset.index):((st.selectedPhoto+(action==='photo-next'?1:-1)+photos.length)%photos.length);
      const im=document.querySelector('.detail-image');if(im){im.dataset.fallback='no';im.dataset.fallbackSrc=demoFallback(photos[st.selectedPhoto]);im.src=photos[st.selectedPhoto];}document.getElementById('photo-count').textContent=String(st.selectedPhoto+1);return;
    }
    if(action==='remove-photo'){st.photos.splice(Number(btn.dataset.index),1);document.getElementById('uploaded-gallery').innerHTML=photoTiles();return;}
    if(action==='logout'){await request('/api/auth/logout',{method:'POST',body:'{}'});st.user=null;st.csrf=null;notify('Signed out securely.');setRoute('/');return;}
    if(action==='delete-listing'){
      if(!confirm(`Remove listing ${btn.dataset.name}? It will be hidden from public search; inquiry history is preserved.`))return;
      await request(`/api/portal/listings/${btn.dataset.id}`,{method:'DELETE',body:'{}'});notify('Property removed from public listings.');await portalListings();return;
    }
    if(action==='edit-team'){teamModal(Number(btn.dataset.id));return;}
    if(action==='edit-lead'){leadModal(Number(btn.dataset.id));return;}
    if(action==='retry-email'){const r=await request('/api/portal/leads/'+btn.dataset.id+'/retry-email',{method:'POST',body:'{}'});notify(r.message);await portalLeads();return;}
    if(action==='reset-team'){
      if(!confirm('Reset this adviser password? Existing sessions will be revoked.'))return;
      const r=await request(`/api/portal/team/${btn.dataset.id}/reset-password`,{method:'POST',body:'{}'});
      modal(`<div class="modal-header"><h2>New temporary password</h2><button data-action="close-modal">${icon('close')}</button></div><div class="modal-body"><p>This password is displayed once. Share it privately with your agent.</p><div class="new-password">${e(r.password)}</div><button class="btn-primary full" data-action="copy-password" data-value="${e(r.password)}">Copy password ${icon('check')}</button></div>`);return;
    }
    if(action==='copy-password'){await navigator.clipboard.writeText(btn.dataset.value);notify('Copied to clipboard.');return;}
    if(action==='sample-csv'){fileDownload('marina-gate-import-template.csv',st.importCSV);return;}
  }catch(err){notify(err.message,'error');}
});
document.addEventListener('submit',async ev=>{
  const form=ev.target;if(!form.id)return;
  if(!['home-search','catalog-filters','login-form','inquiry-form','property-form','import-form','team-form','password-form','lead-notes-form'].includes(form.id))return;
  ev.preventDefault();const button=form.querySelector('[type="submit"],button:not([type])');if(st.busy)return;st.busy=true;
  if(button){button.disabled=true;button.classList.add('submitting');}
  try{
    if(form.id==='home-search'||form.id==='catalog-filters'){
      const p=getValues(form);const next=Object.fromEntries(Object.entries(p).filter(([,v])=>v!==''));if(form.id==='catalog-filters')next.sort=document.getElementById('catalog-sort')?.value||'newest';setRoute('/properties?'+new URLSearchParams(next));return;
    }
    if(form.id==='login-form'){
      const r=await request('/api/auth/login',{method:'POST',body:JSON.stringify(getValues(form))});st.user=r.user;st.csrf=r.csrf;notify('Welcome back, '+r.user.name.split(' ')[0]+'.');setRoute('/portal');return;
    }
    if(form.id==='inquiry-form'){
      const r=await request('/api/inquiries',{method:'POST',body:JSON.stringify(getValues(form))});
      modal(`<div class="success-modal">${icon('check',40)}<h2>Thank you for<br><em>getting in touch.</em></h2><p>${e(r.notice)} Our team can now follow up with you.</p><span>YOUR REFERENCE · ${e(r.reference)}</span><button class="btn-primary full" data-action="close-modal">Continue exploring ${icon('arrow')}</button></div>`);form.reset();return;
    }
    if(form.id==='property-form'){
      const data=getValues(form);data.amenities=Array.from(form.querySelectorAll('[name="amenities"]:checked')).map(x=>x.value);
      data.photos=st.photos;data.featured=!!form.querySelector('[name="featured"]:checked');data.furnished=data.furnished==='yes';
      const p=st.editProperty;const endpoint=p?`/api/portal/listings/${p.id}`:'/api/portal/listings';
      await request(endpoint,{method:p?'PATCH':'POST',body:JSON.stringify(data)});notify(p?'Listing updated successfully.':'New listing created successfully.');setRoute('/portal/listings');return;
    }
    if(form.id==='password-form'){
      const data=getValues(form);
      if(data.new_password!==data.confirm_password)throw Error('New passwords do not match.');
      await request('/api/auth/change-password',{method:'POST',body:JSON.stringify({current_password:data.current_password,new_password:data.new_password})});
      form.reset();notify('Password changed. Other sessions have been signed out.');return;
    }
    if(form.id==='lead-notes-form'){
      const data=getValues(form);
      await request('/api/portal/leads/'+form.dataset.id,{method:'PATCH',body:JSON.stringify(data)});
      document.querySelector('.modal-overlay')?.remove();notify('Follow-up saved.');await portalLeads();return;
    }
    if(form.id==='team-form'){
      const data=getValues(form);data.active=!!form.querySelector('[name="active"]:checked');
      await request('/api/portal/team/'+form.dataset.id,{method:'PATCH',body:JSON.stringify(data)});document.querySelector('.modal-overlay')?.remove();notify('Adviser profile updated.');await portalTeam();return;
    }
    if(form.id==='import-form'){
      const f=form.querySelector('#import-file').files[0];if(!f)throw Error('Select a CSV file.');if(f.size>2*1024*1024)throw Error('CSV is too large.');
      const r=await request('/api/portal/import',{method:'POST',body:JSON.stringify({csv:await f.text()})});
      document.getElementById('import-results').innerHTML=`<div class="import-success">${icon('check',23)} Imported ${r.imported} new · Updated ${r.updated} existing records.<p>${e(r.warning)}</p></div>`;
      notify('CSV import finished.');return;
    }
  }catch(err){notify(err.message,'error');if(form.id==='import-form'&&err.message){document.getElementById('import-results').textContent=err.message;}}
  finally{st.busy=false;if(button){button.disabled=false;button.classList.remove('submitting');}}
});
document.addEventListener('change',async ev=>{
  const el=ev.target;
  if(el.name==='type'&&el.closest('#property-form')){
     const f=el.closest('form'),isPlot=el.value==='Plot';
     if(isPlot){if(f.elements.bedrooms)f.elements.bedrooms.value='0';if(f.elements.bathrooms)f.elements.bathrooms.value='0';}
     else if(f.elements.bathrooms&&Number(f.elements.bathrooms.value)===0)f.elements.bathrooms.value='1';
   }
   if(el.id==='catalog-sort'){const q=Object.fromEntries(new URLSearchParams(location.search));setRoute('/properties?'+new URLSearchParams({...q,sort:el.value,page:1}));return;}
  if(el.id==='property-images'){
    const files=Array.from(el.files||[]);const status=document.getElementById('upload-status');if(st.photos.length+files.length>20){notify('Up to 20 photos per listing.','error');return;}
    el.disabled=true;try{let done=0;for(const f of files){status.textContent=`Optimizing & uploading photo ${done+1} of ${files.length}…`;st.photos.push(await uploadFile(f));document.getElementById('uploaded-gallery').innerHTML=photoTiles();done++;}status.textContent=`${done} photo${done===1?'':'s'} uploaded and optimized.`;notify('Photos added.');}catch(err){status.textContent=err.message;notify(err.message,'error');}finally{el.disabled=false;el.value='';}return;
  }
  if(el.classList.contains('lead-select')){
    try{await request('/api/portal/leads/'+el.dataset.leadId,{method:'PATCH',body:JSON.stringify({status:el.value})});notify('Lead status updated.');}catch(err){notify(err.message,'error');await portalLeads();}return;
  }
});
